// Generates src/TurtleRoute.OpenCage/AddressFormattingData.g.cs from OpenCage's address-formatting project.
// Run from anywhere: dotnet run tools/address-formatting/Generate.cs [commit]
// Without a commit it uses the one in the current generated file; pass "master" to move to the latest.

using System.Runtime.CompilerServices;
using System.Text;
using System.Text.RegularExpressions;

string here = Here();
string output = Path.GetFullPath(Path.Combine(here, "..", "..", "src", "TurtleRoute.OpenCage", "AddressFormattingData.g.cs"));
string commit = args.Length > 0 ? args[0] : CurrentCommit(output) ?? "master";

using HttpClient http = new() { DefaultRequestHeaders = { { "User-Agent", "TurtleRoute-generator" } } };
if (!Regex.IsMatch(commit, "^[0-9a-f]{40}$"))
{
    string json = await http.GetStringAsync($"https://api.github.com/repos/OpenCageData/address-formatting/commits/{commit}");
    commit = Regex.Match(json, "\"sha\":\\s*\"([0-9a-f]{40})\"").Groups[1].Value;
}

string Raw(string path) => $"https://raw.githubusercontent.com/OpenCageData/address-formatting/{commit}/{path}";

string listing = await http.GetStringAsync($"https://api.github.com/repos/OpenCageData/address-formatting/contents/conf/abbreviations?ref={commit}");
string[] languages = [.. Regex.Matches(listing, "\"name\":\\s*\"([a-z]+)\\.yaml\"").Select(m => m.Groups[1].Value).Order()];

// Road abbreviations per language, upstream first, then the supplement for what is missing there.
SortedDictionary<string, List<(string Long, string Short)>> roads = [];
foreach (string language in languages)
{
    string yaml = await http.GetStringAsync(Raw($"conf/abbreviations/{language}.yaml"));
    roads[language] = [.. Sections(yaml).Where(e => e.Section == "road").Select(e => (e.Key, e.Value))];
}

List<string> supplemented = [];
foreach ((string language, string longForm, string shortForm) in Sections(File.ReadAllText(Path.Combine(here, "supplement.yaml"))))
{
    if (!roads.TryGetValue(language, out var entries))
        roads[language] = entries = [];
    if (!entries.Contains((longForm, shortForm)))
    {
        entries.Add((longForm, shortForm));
        supplemented.Add($"{language}: {longForm}: {shortForm}");
    }
}

SortedDictionary<string, string[]> countries = [];
foreach (string line in (await http.GetStringAsync(Raw("conf/country2lang.yaml"))).Split('\n'))
{
    Match m = Regex.Match(line, @"^([A-Z]{2}):\s*(.+?)\s*$");
    if (m.Success)
        countries[m.Groups[1].Value] = [.. m.Groups[2].Value.Split(',').Select(l => l.Trim()).Where(l => l.Length > 0)];
}

string license = await http.GetStringAsync(Raw("LICENSE.txt"));

StringBuilder cs = new();
cs.AppendLine("// <auto-generated>");
cs.AppendLine("// Generated by tools/address-formatting/Generate.cs; do not edit.");
cs.AppendLine($"// Source: https://github.com/OpenCageData/address-formatting/tree/{commit}");
cs.AppendLine("// (conf/abbreviations/*.yaml road sections and conf/country2lang.yaml), plus tools/address-formatting/supplement.yaml.");
cs.AppendLine("//");
foreach (string line in license.TrimEnd().Split('\n'))
    cs.AppendLine(("// " + line.TrimEnd('\r')).TrimEnd());
cs.AppendLine("// </auto-generated>");
cs.AppendLine();
cs.AppendLine("using System.Collections.Generic;");
cs.AppendLine();
cs.AppendLine("namespace TurtleRoute.OpenCage");
cs.AppendLine("{");
cs.AppendLine("    internal static class AddressFormattingData");
cs.AppendLine("    {");
cs.AppendLine($"        public const string Commit = \"{commit}\";");
cs.AppendLine();
cs.AppendLine("        /// <summary>Street abbreviations per language, as (full word, abbreviation).</summary>");
cs.AppendLine("        public static readonly IReadOnlyDictionary<string, (string Long, string Short)[]> RoadAbbreviations = new Dictionary<string, (string, string)[]>");
cs.AppendLine("        {");
foreach ((string language, var entries) in roads)
    cs.AppendLine($"            [\"{language}\"] = [{string.Join(", ", entries.Select(e => $"({Literal(e.Long)}, {Literal(e.Short)})"))}],");
cs.AppendLine("        };");
cs.AppendLine();
cs.AppendLine("        /// <summary>The languages of each country, by ISO 3166-1 alpha-2 code.</summary>");
cs.AppendLine("        public static readonly IReadOnlyDictionary<string, string[]> CountryLanguages = new Dictionary<string, string[]>");
cs.AppendLine("        {");
foreach ((string country, string[] langs) in countries)
    cs.AppendLine($"            [\"{country}\"] = [{string.Join(", ", langs.Select(Literal))}],");
cs.AppendLine("        };");
cs.AppendLine("    }");
cs.AppendLine("}");

File.WriteAllText(output, cs.ToString().ReplaceLineEndings("\n"));
Console.WriteLine($"Wrote {output}: {roads.Sum(r => r.Value.Count)} abbreviations in {roads.Count} languages, {countries.Count} countries, commit {commit}.");
foreach (string entry in supplemented)
    Console.WriteLine($"  from supplement.yaml: {entry}");

// "section:" lines followed by indented "Key: Value" lines.
static IEnumerable<(string Section, string Key, string Value)> Sections(string yaml)
{
    string? section = null;
    foreach (string raw in yaml.Split('\n'))
    {
        string line = raw.TrimEnd('\r');
        if (line.Trim().Length == 0 || line.TrimStart().StartsWith('#'))
            continue;

        int colon = line.IndexOf(':');
        if (colon < 0)
            continue;

        if (!char.IsWhiteSpace(line[0]))
        {
            section = line[..colon].Trim();
            continue;
        }

        string key = line[..colon].Trim(), value = line[(colon + 1)..].Trim().Trim('"', '\'');
        if (section != null && key.Length > 0 && value.Length > 0)
            yield return (section, key, value);
    }
}

static string Literal(string value) => "\"" + value.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\"";

static string? CurrentCommit(string path)
    => File.Exists(path) ? Regex.Match(File.ReadAllText(path), "Commit = \"([0-9a-f]{40})\"") is { Success: true } m ? m.Groups[1].Value : null : null;

static string Here([CallerFilePath] string path = "") => Path.GetDirectoryName(path)!;
